interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

const PROCESSING_FEE = 5;
const COMPONENT_BASE_PREMIUM = 25;

const itemBasePremium = (item: Item): number => {
  return COMPONENT_BASE_PREMIUM;
};

const quotePremium = (step: QuoteStep): number => {
  let total = 0;
  for (const item of step.items) {
    const base = itemBasePremium(item);
    total += base + base * 0.1; // first-insurance surcharge per item
  }
  return total + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): { results: unknown[] } => {
  const results = scenario.steps.map((step) => ({
    premium: quotePremium(step),
  }));
  return { results };
};

