interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

const PROCESSING_FEE = 5;
const COMPONENT_BASE_PREMIUM = 25;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const componentsBasePremium = (items: Item[]): number => {
  const countsByType = new Map<string, number>();
  for (const item of items) {
    countsByType.set(item.type, (countsByType.get(item.type) ?? 0) + 1);
  }
  let total = 0;
  for (const count of countsByType.values()) {
    if (count === COMPONENT_BLOCK_SIZE) {
      total += COMPONENT_BLOCK_PREMIUM;
    } else {
      total += count * COMPONENT_BASE_PREMIUM;
    }
  }
  return total;
};

const quotePremium = (step: QuoteStep): number => {
  const components = step.items.filter((item) => COMPONENT_TYPES.has(item.type));
  const baseTotal = componentsBasePremium(components);
  const withFirstInsurance = baseTotal + baseTotal * FIRST_INSURANCE_SURCHARGE;
  return Math.ceil(withFirstInsurance + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): { results: unknown[] } => {
  const results = scenario.steps.map((step) => ({
    premium: quotePremium(step),
  }));
  return { results };
};

