import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Base premiums for main items (single item, no modifiers, newcomer with 0 years) ---
  // Note: a lone quote for a newcomer applies first-insurance surcharge + fee.
  // Simplest possible: empty item list.
  it("empty item list -> premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });
    expect(result.results[0]).toEqual({ premium: 5 });
  });

  // --- Components base premiums / building blocks ---
  it("2 runes -> 50 G base premium (total 60 G for newcomer)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });
    // base 50 + 10% first-insurance (5) + 5 fee = 60
    expect(result.results[0]).toEqual({ premium: 60 });
  });
  it("3 runes -> 60 G base premium (block applies)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] },
      ],
    });
    // block base 60 + 10% first-insurance (6) + 5 fee = 71
    expect(result.results[0]).toEqual({ premium: 71 });
  });
  it("4 runes -> 100 G base premium (no block)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    });
    // base 100 + 10% (10) + 5 fee = 115
    expect(result.results[0]).toEqual({ premium: 115 });
  });
  it("7 runes -> 175 G base premium (no block, total rounds to 198)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: Array.from({ length: 7 }, () => ({ type: "rune" })),
        },
      ],
    });
    // base 175 + 10% (17.5) + 5 fee = 197.5 -> rounded up to 198
    expect(result.results[0]).toEqual({ premium: 198 });
  });
  it("2 runes + 1 moonstone -> 75 G base premium (no block: different types)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
        },
      ],
    });
    // base 75 + 10% (7.5) + 5 fee = 87.5 -> ceil 88
    expect(result.results[0]).toEqual({ premium: 88 });
  });
  it("3 runes + 3 moonstones -> 120 G base premium (two separate blocks)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "moonstone" },
            { type: "moonstone" },
            { type: "moonstone" },
          ],
        },
      ],
    });
    // two blocks: 60 + 60 = 120 + 10% (12) + 5 fee = 137
    expect(result.results[0]).toEqual({ premium: 137 });
  });

  // --- Modifier scope on multi-item policies ---
  it("cursed sword + plain amulet -> curse on cursed item only (210 before modifiers/fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 3, cursed: true },
            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
          ],
        },
      ],
    });
    // policy base 160, curse +50 (50% of sword 100) = 210; first-insurance 10% of 160 = 16; +5 fee = 231
    expect(result.results[0]).toEqual({ premium: 231 });
  });
  it.todo("policy-wide modifiers apply to policy base premium; item modifiers to item base");

  // --- Modifier thresholds ---
  it.todo("customer with exactly 2 years -> loyalty discount applies");
  it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge applies");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge");

  // --- Rounding ---
  it.todo("premium yielding 197.5 G -> 198 G (rounded up)");
  it.todo("payout yielding 350.5 G -> 350 G (rounded down)");

  // --- Integration examples ---
  it.todo("newcomer with a cursed sword -> premium 165 G");
  it.todo("long-standing customer's second contract -> premium 160 G");

  // --- Claim processing: standard reimbursement ---
  it.todo("regular sword, damage 500 G -> payout 400 G");
  it.todo("rune damage 200 G -> payout 100 G");

  // --- Claim: enchantment threshold vs dragon material ---
  it.todo("dragon-material sword ench 8, damage 1000 G -> payout 400 G");
  it.todo("dragon-material sword ench 9, damage 1000 G -> payout 400 G (50% wins)");
  it.todo("dragon-material sword ench 5, damage 800 G -> payout 700 G (dragon full)");
  it.todo("steel sword ench 9, damage 1000 G -> payout 400 G (50% then deductible)");

  // --- Deductible per damage event ---
  it.todo("dragon attack damages sword 500 + amulet 300 -> payout 600 G (deductible per item)");

  // --- Multiple items of same type ---
  it.todo("two swords -> insurance sum 2000 G, cap 4000 G");
  it.todo("dragon attack damages both swords -> each damage separate deductible");
  it.todo("more damages of a type than insured -> claim rejected (non-zero exit)");

  // --- Cap exhaustion ---
  it.todo("sword + amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword -> cap 2000 G (based on unmodified insurance value)");
  it.todo("sword + 3 runes block -> insurance sum 1750 G");
  it.todo("two successive 1500 G claims -> 1400 then 600, cap exhausted");

  // --- Edge cases ---
  it.todo("unknown item type in quote -> non-zero exit, error to stderr");
  it.todo("claim references item not in policy -> non-zero exit");
  it.todo("claim with negative amount -> non-zero exit");
});

