const itemInsuranceValue = (item: Item): number => {
  return MAIN_ITEM_INSURANCE_VALUE[item.type] ?? COMPONENT_INSURANCE_VALUE;
};

const insuranceSum = (items: Item[]): number => {
  return items.reduce((sum, item) => sum + itemInsuranceValue(item), 0);
};

interface Policy {
  items: Item[];
  remainingCap: number;
}

const damagePayout = (damage: Damage): number => {
  return Math.floor(damage.amount - DEDUCTIBLE);
};

const processClaim = (
  step: ClaimStep,
  policy: Policy
): { payout: number; remainingCap: number } => {
  let payout = 0;
  for (const damage of step.incident.damages) {
    payout += damagePayout(damage);
  }
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};

export const runScenario = (scenario: Scenario): { results: unknown[] } => {
  const policies: Policy[] = [];
  const results = scenario.steps.map((step) => {
    if (step.op === "quote") {
      policies.push({
        items: step.items,
        remainingCap: insuranceSum(step.items) * CAP_MULTIPLIER,
      });
      return { premium: quotePremium(step, scenario.customer) };
    }
    return processClaim(step, policies[step.policy]);
  });
  return { results };
};

const itemInsuranceValue = (item: Item): number => {
  return MAIN_ITEM_INSURANCE_VALUE[item.type] ?? COMPONENT_INSURANCE_VALUE;
};

const insuranceSum = (items: Item[]): number => {
  return items.reduce((sum, item) => sum + itemInsuranceValue(item), 0);
};

