const assertDamagesCovered = (step: ClaimStep, policy: Policy): void => {
  const insuredCounts = new Map<string, number>();
  for (const item of policy.items) {
    insuredCounts.set(item.type, (insuredCounts.get(item.type) ?? 0) + 1);
  }
  const claimedCounts = new Map<string, number>();
  for (const damage of step.incident.damages) {
    claimedCounts.set(damage.itemType, (claimedCounts.get(damage.itemType) ?? 0) + 1);
  }
  for (const [type, claimed] of claimedCounts) {
    if (claimed > (insuredCounts.get(type) ?? 0)) {
      throw new Error(`Claim rejected: ${claimed} ${type} damages but not enough insured`);
    }
  }
};

